def load_tpl():
    try: return json.load(open(TPL))
    except: pass
    try:
        import gzip, base64
        return json.loads(gzip.decompress(base64.b64decode(TPL_EMBEDDED)))
    except: return {}
TPLC = None
def show(r):
    if not VERBOSE: return
    if r["status"] in ("FAIL", "PASS"): return
    global TPLC
    sym = {"PASS": "\033[32m\u2713\033[0m", "FAIL": "\033[31m\u2717\033[0m"}.get(r["status"], "\033[33m~\033[0m")
    if r["status"] == "FAIL":
        if TPLC is None:
            TPLC = load_tpl()
        t = to_tpl(r["id"], r["desc"], CUR_PROV)
        if t is None:
            line = f"  {sym} {r['id']} {r['desc'][:60]}  \033[37m[UNMAPPED]\033[0m no finding template"
        else:
            risk = tget(TPLC, t).get("risk", "Medium").upper()
            col = {"HIGH": 31, "CRITICAL": 35, "MEDIUM": 33, "LOW": 36}.get(risk, 37)
            line = f"  {sym} {r['id']}  \033[{col}m[{risk}]\033[0m \033[1m{t}\033[0m"
    else:
        line = f"  {sym} {r['id']} {r['desc'][:80]}"
    print(line)

def raw_lines(res, evid=""):
    """pretty raw JSON lines + set of line indexes belonging to offending objects (matched by evidence)"""
    raw = RAWJSON.get(res or "")
    if not raw: return [], set()
    bad = {p.strip() for chunk in (evid or "").split(",") for p in chunk.split(";") if p.strip()}
    try: data = json.loads(raw)
    except: data = None
    if not isinstance(data, dict) or not isinstance(data.get("items"), list):
        return raw.splitlines(), set()
    lines = ["{", ' "items": [']
    hit = set()
    items = data["items"]
    for i, it in enumerate(items):
        md = it.get("metadata", {}) if isinstance(it, dict) else {}
        nm, ns = md.get("name", ""), md.get("namespace", "")
        keys = {nm, f"{ns}/{nm}", f"{ns}/{nm}@{it.get('spec', {}).get('nodeName', '?')}"}
        il = ["  " + l for l in json.dumps(it, indent=1).splitlines()]
        if i < len(items) - 1: il[-1] += ","
        if bad & keys:
            hit.update(range(len(lines), len(lines) + len(il)))
        lines.extend(il)
    lines += [" ]", "}"]
    return lines, hit

def print_raw(res, evid=""):
    if not RAWJSON.get(res or ""): return
    lines, hit = raw_lines(res, evid)
    tot, cut = 0, len(lines)
    for i, l in enumerate(lines):
        tot += len(l) + 1
        if tot > RAWMAX:
            cut = i + 1
            break
    trunc = cut < len(lines)
    nbad = sum(1 for i in hit if i < cut and (i - 1) not in hit)
    hdr = f"      vulnerable raw output (kubectl get {res}"
    hdr += ", truncated" if trunc else ""
    hdr += (f"; {nbad} offending object(s) highlighted red" if nbad else "") + "; full copy in results.json raw_outputs):"
    print(hdr)
    for i, l in enumerate(lines[:cut]):
        print("        " + (f"\033[31;1m{l}\033[0m" if i in hit else l))
    if trunc: print("        ... (truncated)")
    if not hit:
        print("        (no offending objects inside the raw output - the issue is what is ABSENT; see vulnerable items below)")

def have(c): return shutil.which(c) is not None
SHOW_CMD = False
def sh(c, t=60):
    try:
        r = subprocess.run(c, shell=True, capture_output=True, text=True, timeout=t)
        if SHOW_CMD:
            print(f"\n\033[36m$ {c}\033[0m")
            body = (r.stdout or "").strip()
            err = (r.stderr or "").strip()
            if body: print(body[:4000])
            if err and r.returncode != 0: print(f"\033[31m{err[:800]}\033[0m")
        return r.returncode, r.stdout, r.stderr
    except subprocess.TimeoutExpired:
        return 124, "", "timeout"
MISSING_PERMS = []
NORISK = set()
DENIED = set()
PARTIAL = {}
RAWJSON = {}
RAWCMD = {}
CUR_RES = None
RAWMAX = int(os.environ.get("CISK8S_RAW_MAX", "3000"))
RAWCFG = {}
def note_perm(err):
    m = re.search(r'cannot (list|get|watch|create|delete|update|patch) resources? "([^"]+)"(?: in API group "([^"]*)")?', err or "")
    if m:
        MISSING_PERMS.append(f"Kubernetes RBAC: allow '{m.group(1)}' on '{m.group(2)}'" + (f" (api group {m.group(3)})" if m.group(3) else ""))
        return True
    m = re.search(r'not authorized to perform: ([a-z0-9:*_-]+)', err or "", re.I)
    if m:
        MISSING_PERMS.append(f"AWS IAM: allow action '{m.group(1)}'")
        return True
    if "AccessDenied" in (err or "") or "UnauthorizedOperation" in (err or ""):
        MISSING_PERMS.append("AWS IAM: " + (err.strip().splitlines() or [""])[-1][:120])
        return True
    return False

def tget(tpl, t):
    """template lookup: exact, then case-insensitive"""
    if t in tpl: return tpl[t]
    tl = (t or "").lower()
    for k, v in tpl.items():
        if k.lower() == tl: return v
    return {}

def ipr(c):
    """CIDR -> plain range (0.0.0.0/0 -> 0.0.0.0-255.255.255.255, /32 -> single ip)"""
    try:
        n = ipaddress.ip_network(str(c), strict=False)
        return str(n.network_address) if n.prefixlen == n.max_prefixlen else f"{n.network_address}-{n.broadcast_address}"
    except Exception:
        return str(c)

def jsh(c, res=None):
    rc, o, e = sh(c)
    if res: RAWCMD[res] = c
    m2 = re.search(r'cannot (?:list|get|watch|create) resources? "([^"]+)"', e or "") or re.search(r'"?(\w[\w.-]*)"? is forbidden', e or "")
    if m2:
        DENIED.add(m2.group(1))
        return None
    try:
        d = json.loads(o)
        if res: RAWJSON[res] = o
        return d
    except:
        if rc != 0: note_perm(e)
        return None

def detect_provider():
    if have("kubectl"):
        n = jsh("kubectl get nodes -o json")
        if n:
            lbl = " ".join(" ".join(x["metadata"].get("labels", {}).keys()) for x in n.get("items", []))
            ctx = jsh("kubectl config view -o json") or {}
            cur = str(ctx.get("current-context", ""))
            s = (lbl + " " + cur).lower()
            if "eks.amazonaws.com" in s or ".eks." in s: return "eks"
            if "kubernetes.azure.com" in s or "aks" in s: return "aks"
            if "cloud.google.com" in s or "gke" in s: return "gke"
            if "oraclecloud" in s or "oke" in s: return "oke"
            if "alibabacloud" in s or "ack" in s: return "ack"
            if "openshift" in s: return "openshift"
            return "vanilla"
    for p, c in [("eks", "aws"), ("aks", "az"), ("gke", "gcloud"), ("oke", "oci"), ("ack", "aliyun"), ("openshift", "oc")]:
        if have(c): return p + "-cli"
    return None

