def docker_up():
    if IS_WIN: return False
    if not have("docker"): return False
    return sh("docker version --format {{.Server.Version}}")[0] == 0

def docker_bench_cmd(b):
    cfg = kb_cfg()
    mounts = f'-v "{cfg}:/etc/kube-bench/cfg"' if os.path.isdir(cfg) else ""
    return f'docker run --rm --pid=host {mounts} aquasec/kube-bench:latest run --json --benchmark {b}'

def run_bench(prov):
    b = BENCH.get(prov)
    if docker_up():
        c = docker_bench_cmd(b)
    elif have("kube-bench") or os.path.isfile(kb_bin()):
        c = f'"{kb_bin()}" run --json' if os.path.sep in kb_bin() else f"{kb_bin()} run --json"
        if os.path.isdir(kb_cfg()):
            c += f' --config-dir "{kb_cfg()}"'
    else:
        msg = "node-level checks are only useful on a cluster node; use --per-node (recommended) or run this tool on a node/bastion with Docker" if IS_WIN else "kube-bench not installed (run --install or install Docker)"
        return None, msg
    if b and "--benchmark" not in c:
        c += f" --benchmark {b}"
    if b:
        print(f"[*] benchmark: {CISDOC.get(b, b)}")
    rc, o, e = sh(c, 300)
    if rc not in (0, 1) or not o.strip().startswith("{"):
        return None, (e or o)[:300]
    return json.loads(o), None

# ---------------- built-in API checks (kubectl, provider-agnostic) ----------------
KVER = None
def per_ns(cmd, res):
    """iterate namespaces with --namespace; returns combined items, None if denied everywhere"""
    if not NSLIST: return []
    out = []
    denied = []
    for n in NSLIST:
        ncmd = cmd.replace(" -A ", f" --namespace {n} ").replace("-A", f"--namespace {n}")
        rc, o, e = sh(ncmd)
        if re.search(r'cannot (list|get|watch)|is forbidden|Forbidden', e or ""):
            denied.append(n)
            continue
        if rc != 0:
            continue
        try:
            items = json.loads(o).get("items", [])
            out.extend(items)
        except Exception:
            pass
    if denied and len(denied) == len(NSLIST):
        DENIED.add(res)
        return None
    if denied:
        print(f"    (no access in {len(denied)} namespace(s): " + ", ".join(denied[:6]) + (", ..." if len(denied) > 6 else "") + ")")
    PARTIAL[res] = denied
    RAWJSON[res] = json.dumps({"items": out})
    return out

def get_items(cmd, res):
    """cluster-scope list with per-namespace fallback; DENIED = no data at all, PARTIAL = fallback used"""
    d = jsh(cmd, res)
    if d is not None:
        return d.get("items", [])
    if NSLIST:
        print(f"[*] {res}: cluster-scope denied, falling back to per-namespace queries across {len(NSLIST)} namespace(s)")
        items = per_ns(cmd, res)
        if items is not None:
            DENIED.discard(res)
            return items
    DENIED.add(res)
    return []

NSLIST = []

def api_checks():
    global KVER, DENIED, NSLIST, CUR_RES
    out = []
    if not have("kubectl") and not have("kubectl.exe"):
        print("[-] kubectl not found - run: python3 cis-k8s.py --install")
        return out
    if sh("kubectl version --client")[0] != 0:
        print("[-] kubectl present but broken")
        return out
    rc, o, e = sh("kubectl version -o json 2>/dev/null")
    try:
        KVER = json.loads(o)["serverVersion"]["gitVersion"]
        print(f"[*] cluster Kubernetes version: {KVER}")
    except Exception:
        KVER = None
    rc, o, e = sh("kubectl get nodes --request-timeout=10s")
    if rc != 0:
        if note_perm(e):
            print("[-] connected, but your identity lacks permission - details collected for the platform team")
        else:
            print("[-] kubectl works but cannot reach a cluster - check kubeconfig (EKS: aws eks update-kubeconfig --name <cluster>)")
            print("    " + (e.strip().splitlines() or ["no cluster"])[-1][:120])
        return out
    def add(cid, desc, ok, rem, evid=""):
        r = {"id": cid, "desc": desc, "status": "PASS" if ok else "FAIL", "remediation": rem, "evidence": evid, "src": "api", "res": CUR_RES}
        out.append(r); show(r)

    CUR_RES = "clusterrolebindings"
    crb_d = jsh("kubectl get clusterrolebindings -o json", "clusterrolebindings")
    if crb_d is None:
        DENIED.add("clusterrolebindings")
        print("[-] 5.1.1/5.1.x skipped: cannot list clusterrolebindings (denied, recorded in permissions) - not a finding, no verdict emitted")
    else:
        crb = crb_d.get("items", [])
        bad = [b["metadata"]["name"] for b in crb if any(s.get("name") in ("system:anonymous", "system:unauthenticated") for s in b.get("subjects", []))]
        add("5.1.x", "No RBAC bindings for unauthenticated subjects", not bad, "Remove bindings granting roles to system:anonymous/system:unauthenticated", ",".join(bad))
        adm = [b["metadata"]["name"] for b in crb if b.get("roleRef", {}).get("name") == "cluster-admin" and any(s.get("kind") in ("User", "Group") and not str(s.get("name", "")).startswith("system:") for s in b.get("subjects", []))]
        add("5.1.1", "cluster-admin only used where required", not adm, "Restrict cluster-admin to break-glass admin accounts", ",".join(adm))

    CUR_RES = "clusterroles"
    rol_d = jsh("kubectl get clusterroles -o json", "clusterroles")
    if rol_d is None:
        DENIED.add("clusterroles")
        print("[-] 5.1.2/5.1.3 skipped: cannot list clusterroles (denied, recorded in permissions) - not a finding, no verdict emitted")
    else:
        roles = rol_d.get("items", [])
        wc = [r["metadata"]["name"] for r in roles if any("*" in (ru.get("verbs") or [""]) or "*" in (ru.get("resources") or [""]) for ru in r.get("rules", [])) and not r["metadata"]["name"].startswith("system:")]
        add("5.1.3", "No wildcards in custom Roles/ClusterRoles", not wc, "Replace * verbs/resources with explicit lists", ",".join(wc))
        sec = [r["metadata"]["name"] for r in roles if any("secrets" in (ru.get("resources") or []) and any(v in (ru.get("verbs") or []) for v in ("get", "list", "watch")) for ru in r.get("rules", [])) and not r["metadata"]["name"].startswith("system:")]
        add("5.1.2", "Secret access minimized in custom roles", not sec, "Remove get/list/watch on secrets from roles that do not require it", ",".join(sec))

    # namespaces first: the per-namespace fallback (get_items) depends on NSLIST
    ns = []
    if getattr(ARGS, "namespaces", None):
        NSLIST = list(ARGS.namespaces)
        ns = [{"metadata": {"name": n, "labels": {}}} for n in NSLIST]
        print(f"[*] using {len(NSLIST)} specified namespace(s): " + ", ".join(NSLIST))
    else:
        nsr = jsh("kubectl get namespaces -o json", "namespaces")
        if nsr is None:
            DENIED.add("namespaces")
        else:
            ns = nsr.get("items", [])
        if not ns:
            ctxns = jsh("kubectl config view -o json")
            for c in (ctxns or {}).get("contexts", []):
                nn = c.get("context", {}).get("namespace")
                if nn: ns.append({"metadata": {"name": nn, "labels": {}}})
            if ns: print("[*] namespaces from kubeconfig contexts (cluster-wide list denied)")
        NSLIST = [n["metadata"]["name"] for n in ns] if ns else []
    if NSLIST:
        print(f"[*] checking {len(NSLIST)} namespace(s) individually: " + ", ".join(NSLIST[:10]) + (" ..." if len(NSLIST) > 10 else ""))

    CUR_RES = "pods"
    pods = get_items("kubectl get pods -A -o json", "pods")
    def cnt(f): return [p["metadata"]["namespace"] + "/" + p["metadata"]["name"] + "@" + p.get("spec", {}).get("nodeName", "?") for p in pods if f(p)]
    spec = lambda p: p.get("spec", {})
    cs = lambda p, f: any(f(c) for c in spec(p).get("containers", []))
    sec_c = lambda c: c.get("securityContext", {}) or {}
    if "pods" in DENIED:
        print("[-] 5.2.x pod-security and 5.7.1 checks skipped: cannot list pods (denied, recorded in permissions) - not findings, no verdicts emitted")
    else:
        add("5.2.1", "No privileged containers", not cnt(lambda p: cs(p, lambda c: sec_c(c).get("privileged"))), "Remove securityContext.privileged", ",".join(cnt(lambda p: cs(p, lambda c: sec_c(c).get("privileged")))))
        add("5.2.2", "No hostPID", not cnt(lambda p: spec(p).get("hostPID")), "Set hostPID: false", ",".join(cnt(lambda p: spec(p).get("hostPID"))[:5]))
        add("5.2.3", "No hostIPC", not cnt(lambda p: spec(p).get("hostIPC")), "Set hostIPC: false", ",".join(cnt(lambda p: spec(p).get("hostIPC"))[:5]))
        add("5.2.4", "No hostNetwork", not cnt(lambda p: spec(p).get("hostNetwork")), "Set hostNetwork: false", ",".join(cnt(lambda p: spec(p).get("hostNetwork"))[:5]))
        add("5.2.5", "allowPrivilegeEscalation=false everywhere", not cnt(lambda p: cs(p, lambda c: sec_c(c).get("allowPrivilegeEscalation") is not False)), "Set allowPrivilegeEscalation: false", ",".join(cnt(lambda p: cs(p, lambda c: sec_c(c).get("allowPrivilegeEscalation") is not False))[:5]))
        sens = ("/", "/etc", "/root", "/var/run/docker.sock", "/var/lib/kubelet", "/proc", "/sys")
        hp = cnt(lambda p: any(v.get("hostPath", {}).get("path", "") in sens for v in spec(p).get("volumes", []) if "hostPath" in v))
        add("5.2.x", "No sensitive hostPath mounts", not hp, "Remove hostPath volumes for sensitive paths", ",".join(hp))
        add("5.2.x", "No containers running as UID 0", not cnt(lambda p: cs(p, lambda c: sec_c(c).get("runAsUser") == 0)), "Set runAsNonRoot: true / non-zero runAsUser", ",".join(cnt(lambda p: cs(p, lambda c: sec_c(c).get("runAsUser") == 0))[:5]))
        dn = cnt(lambda p: p["metadata"]["namespace"] == "default")
        add("5.7.1", "default namespace not used for workloads", not dn, "Move workloads out of the default namespace", ",".join(dn))
    sys_ns = {"kube-system", "kube-public", "kube-node-lease", "default"}
    CUR_RES = "namespaces"
    nolbl = []
    _psan = next((n for n in ns if n["metadata"]["name"] not in sys_ns and not any(k.startswith("pod-security.kubernetes.io/enforce") for k in (n["metadata"].get("labels") or {}))), None)
    if _psan:
        _l = _psan["metadata"].get("labels") or {}
        RAWCFG.setdefault("5.2.x", f"kubectl get ns {_psan['metadata']['name']} -o jsonpath='{{.metadata.labels}}' -> " + json.dumps(_l) + "   (no 'pod-security.kubernetes.io/enforce' key present)")
    for n in ns:
        nm = n["metadata"]["name"]
        if nm in sys_ns: continue
        lbls = n["metadata"].get("labels", {}) or {}
        if not any(k.startswith("pod-security.kubernetes.io/enforce") for k in lbls):
            nolbl.append(nm)
    add("5.2.x", "Pod Security Standards enforced on all namespaces", not nolbl, "Label namespaces pod-security.kubernetes.io/enforce=baseline|restricted", ",".join(nolbl))
    CUR_RES = "networkpolicies"
    np = get_items("kubectl get networkpolicies -A -o json", "networkpolicies")
    if "networkpolicies" in DENIED:
        print("[-] 5.3.2 skipped: cannot list networkpolicies (denied, recorded in permissions) - not a finding")
    else:
        if not np:
            RAWCFG['5.3.2'] = 'kubectl get networkpolicies -A -o json -> {"items": []}'
        covered = {p["metadata"]["namespace"] for p in np}
        nonp = [n["metadata"]["name"] for n in ns if n["metadata"]["name"] not in sys_ns and n["metadata"]["name"] not in covered]
        add("5.3.2", "All namespaces have NetworkPolicies", not nonp, "Create default-deny NetworkPolicies per namespace", ",".join(nonp))

    CUR_RES = "serviceaccounts"
    sa = get_items("kubectl get serviceaccounts -A -o json", "serviceaccounts")
    if "serviceaccounts" in DENIED:
        print("[-] 5.1.6 skipped: cannot list serviceaccounts (denied, recorded in permissions) - not a finding, no verdict emitted")
    else:
        am = [s["metadata"]["namespace"] + "/" + s["metadata"]["name"] for s in sa if s.get("automountServiceAccountToken") is True and s["metadata"]["name"] != "default"]
        add("5.1.6", "automountServiceAccountToken disabled unless needed", not am, "Set automountServiceAccountToken: false", ",".join(am))

    CUR_RES = "resourcequotas"
    rq_all = get_items("kubectl get resourcequotas -A -o json", "resourcequotas")
    if "resourcequotas" in DENIED:
        print("[-] 5.4.x quota check skipped: cannot list resourcequotas (denied, recorded in permissions) - not a finding, no verdict emitted")
    else:
        rq = {(x["metadata"]["namespace"]) for x in rq_all}
        if not rq_all:
            RAWCFG['5.4.x-quota'] = 'kubectl get resourcequotas -A -o json -> {"items": []}'
        norq = [n["metadata"]["name"] for n in ns if n["metadata"]["name"] not in sys_ns and n["metadata"]["name"] not in rq]
        add("5.4.x", "All namespaces have ResourceQuotas", not norq, "Create ResourceQuota per namespace (namespace segregation)", ",".join(norq))
    CUR_RES = "limitranges"
    lr_all = get_items("kubectl get limitranges -A -o json", "limitranges")
    if "limitranges" in DENIED:
        print("[-] 5.4.x limitrange check skipped: cannot list limitranges (denied, recorded in permissions) - not a finding, no verdict emitted")
    else:
        lr = {(x["metadata"]["namespace"]) for x in lr_all}
        nolr = [n["metadata"]["name"] for n in ns if n["metadata"]["name"] not in sys_ns and n["metadata"]["name"] not in lr]
        add("5.4.x", "All namespaces have LimitRanges", not nolr, "Create LimitRange per namespace for default requests/limits", ",".join(nolr))

    if CUR_PROV == "eks" and "serviceaccounts" not in DENIED:
        CUR_RES = "serviceaccounts"
        noi = [s["metadata"]["namespace"] + "/" + s["metadata"]["name"] for s in sa
               if s.get("automountServiceAccountToken") is not False and "eks.amazonaws.com/role-arn" not in (s.get("annotations") or {}) and s["metadata"]["name"] != "default"]
        add("EKS-SA", "Service accounts use IRSA instead of node instance role", not noi, "Annotate SAs with eks.amazonaws.com/role-arn (IRSA) or disable automount; node role credentials are otherwise exposed to pods", ",".join(noi))
    return out

# ---------------- extra (non-CIS) template checks ----------------
def extra_checks():
    out = []
    if not have("kubectl"): return out
    if sh("kubectl version --request-timeout=8s")[0] != 0: return out
    global CUR_RES
    CUR_RES = "pods"
    def add(desc, ok, rem, tpl, evid=""):
        r = {"id": "EXTRA", "desc": desc, "status": "PASS" if ok else "FAIL", "remediation": rem, "evidence": evid, "src": "extra", "res": CUR_RES, "template": tpl if not ok else None}
        out.append(r); show(r)
    pods = get_items("kubectl get pods -A -o json", "pods")
    pdenied = "pods" in DENIED
    if pdenied:
        print("[-] EXTRA pod checks skipped: cannot list pods (denied, recorded in permissions) - not findings, no verdicts emitted")
    spec = lambda p: p.get("spec", {})
    cs = lambda p, f: any(f(c) for c in spec(p).get("containers", []))
    def cnt(f): return [p["metadata"]["namespace"] + "/" + p["metadata"]["name"] + "@" + p.get("spec", {}).get("nodeName", "?") for p in pods if f(p)]
    if not pdenied:
        dash = cnt(lambda p: "dashboard" in p["metadata"]["name"].lower() or "dashboard" in p["metadata"]["namespace"].lower())
        add("Kubernetes dashboard not deployed", not dash, "Remove the Kubernetes dashboard or restrict access", "Kubernetes Web UI (Dashboard) Enabled", ",".join(dash))

        nolim = cnt(lambda p: cs(p, lambda c: not (c.get("resources", {}).get("limits", {}).get("memory") and c.get("resources", {}).get("limits", {}).get("cpu"))))
        add("All containers have CPU/memory limits", not nolim, "Set resources.limits on every container", "Container Resource Limits Not in Place", ",".join(nolim))

        bare = cnt(lambda p: not p["metadata"].get("ownerReferences"))
        add("No bare pods (all pods owned by a workload controller)", not bare, "Use Deployments/StatefulSets/Jobs instead of bare pods", "Pods Without Parental Workload", ",".join(bare))

        imgs = [(c.get("image", "") or "") for p in pods for c in spec(p).get("containers", [])]
        pub = sorted({i for i in imgs if i and "." not in i.split("/")[0] and "/" not in i.split("/")[0]})
        add("No images from public/anonymous registries", not pub, "Pull images from a private/approved registry", "Public Container Image Repositories Accessible", ",".join(pub))

        lat = sorted({i for i in imgs if i.endswith(":latest") or ":" not in i})
        add("No mutable image tags (:latest / untagged)", not lat, "Pin images to an immutable tag or digest", "Mutable Containers", ",".join(lat))

        hp = cnt(lambda p: cs(p, lambda c: any(pp.get("hostPort") for pp in c.get("ports", []) or [])))
        add("No hostPort exposures", not hp, "Remove hostPort; use Services instead", "Docker Container Ports Open", ",".join(hp))

        noss = cnt(lambda p: not (spec(p).get("securityContext", {}) or {}).get("seccompProfile") and not cs(p, lambda c: (c.get("securityContext", {}) or {}).get("seccompProfile")))
        add("seccomp profiles set on all pods", not noss, "Set securityContext.seccompProfile (RuntimeDefault minimum)", "AppArmor/SELinux Profiles Not Set on Containers", ",".join(noss))

        envsec = cnt(lambda p: cs(p, lambda c: any("secret" in str((e.get("valueFrom") or {}).get("secretKeyRef", "")) or True for e in c.get("env", []) or [] if (e.get("valueFrom") or {}).get("secretKeyRef"))))
        add("No secrets exposed as environment variables", not envsec, "Mount secrets as volumes instead of env vars", "Insecure Container Secret Storage", ",".join(envsec))

    CUR_RES = "clusterpolicies"
    ky = jsh("kubectl get clusterpolicies.kyverno.io -o json", "clusterpolicies")
    if ky and ky.get("items"):
        aud = [k["metadata"]["name"] for k in ky["items"] if str(k.get("spec", {}).get("validationFailureAction", "")).lower() == "audit"]
        add("Kyverno policies enforce (not audit-only)", not aud, "Set validationFailureAction: Enforce", "Kubernetes - Kyverno Policies Set to Audit", ",".join(aud))
    return out

# ---------------- provider CLI checks ----------------
def cli_checks(prov):
    out = []
    def add(cid, desc, ok, rem, evid=""):
        r = {"id": cid, "desc": desc, "status": "PASS" if ok else "FAIL", "remediation": rem, "evidence": evid, "src": "cli"}
        out.append(r); show(r)
    if prov == "eks" and not have("aws"):
        print("[-] eks control-plane checks skipped: aws CLI not found")
    if prov == "eks" and have("aws"):
        ctx = sh("kubectl config current-context")[1].strip() if have("kubectl") else ""
        rg = ""
        if ctx.count(":") >= 3 and "eks" in ctx:
            rg = " --region " + ctx.split(":")[3]
        rc, o, e = sh(f"aws eks list-clusters{rg} --output json")
        cl = None
        try: cl = json.loads(o)
        except Exception: pass
        list_err = None
        if cl is None:
            note_perm(e)
            list_err = (e.strip().splitlines() or ["unknown error"])[-1][:120]
        elif not cl.get("clusters"):
            list_err = "no clusters returned by aws eks list-clusters"
        cl = cl or {}
        names = cl.get("clusters", [])
        if not names and ctx:
            cn = ctx.split("/")[-1]
            names = [cn]
            print(f"[*] eks control-plane checks: cluster '{cn}' (from kubeconfig; list-clusters unavailable)")
        if not names and list_err:
            print(f"[-] eks control-plane checks skipped: {list_err}")
        for n in names:
            d = jsh(f"aws eks describe-cluster --name {n}{rg} --output json") or {}
            c = d.get("cluster", {})
            lg = c.get("logging", {}).get("clusterLogging", [{}])
            on = set(lg[0].get("types", [])) if lg and lg[0].get("enabled") else set()
            add("2.1.1", f"[{n}] Control plane audit logging enabled", "audit" in on, "Enable 'audit' (and api/authenticator) log types", str(sorted(on)))
            ep = c.get("resourcesVpcConfig", {})
            cidrs = ";".join(ipr(c) for c in (ep.get("publicAccessCidrs") or []))
            add("3.1.1", f"[{n}] API endpoint not publicly accessible", not ep.get("endpointPublicAccess"), "Disable endpointPublicAccess or restrict publicAccessCidrs", f"public={ep.get('endpointPublicAccess')};{cidrs}")
            add("4.1.1", f"[{n}] Secrets encrypted with KMS", bool(c.get("encryptionConfig")), "Associate a KMS key via encryptionConfig", str(c.get("encryptionConfig")))
            try: ve = float(c.get("version", "0"))
            except: ve = 0.0
            add("5.1.1", f"[{n}] Supported Kubernetes version", ve >= 1.28, "Upgrade cluster to a supported version", c.get("version", ""))
    if prov == "aks" and not have("az"):
        print("[-] aks cli checks skipped: az CLI not found")
    if prov == "aks" and have("az"):
        cl = jsh("az aks list -o json") or []
        for c in cl:
            n = c.get("name")
            add("5.2.1", f"[{n}] RBAC enabled", c.get("enableRBAC"), "Enable Kubernetes RBAC / Azure AD integration", str(c.get("enableRBAC")))
            add("5.4.1", f"[{n}] Azure Policy add-on enabled", (c.get("azurePolicyEnabled") or (c.get("addonProfiles", {}).get("azurepolicy", {}).get("enabled"))), "Enable the Azure Policy add-on", "")
            mon = c.get("addonProfiles", {}).get("omsagent", {}).get("enabled")
            add("5.1.x", f"[{n}] Container insights / monitoring enabled", bool(mon), "Enable Container insights (omsagent)", "")
            add("6.1.1", f"[{n}] Private cluster", bool(c.get("apiServerAccessProfile", {}).get("enablePrivateCluster")), "Enable private cluster", ";".join(ipr(x) for x in (c.get("apiServerAccessProfile", {}).get("authorizedIPRanges") or [])))
            add("5.2.2", f"[{n}] Local accounts disabled", bool(c.get("disableLocalAccounts")), "Set --disable-local-accounts", "")
            try: va = float(".".join(str(c.get("kubernetesVersion", "0")).split(".")[:2]))
            except: va = 0.0
            add("5.3.1", f"[{n}] Supported version", va >= 1.28, "Upgrade cluster", c.get("kubernetesVersion", ""))
    if prov == "gke" and not have("gcloud"):
        print("[-] gke cli checks skipped: gcloud CLI not found")
    if prov == "gke" and have("gcloud"):
        rc, o, e = sh("gcloud container clusters list --format=json")
        try: cl = json.loads(o)
        except: cl = []
        for c in cl:
            n = c.get("name")
            add("5.6.2", f"[{n}] Legacy ABAC disabled", not c.get("legacyAbac", {}).get("enabled"), "Disable legacyAbac", "")
            ma = c.get("masterAuth", {})
            add("5.6.1", f"[{n}] Basic authentication disabled", not ma.get("username"), "Set an empty masterAuth username/password", "")
            add("5.6.3", f"[{n}] Private cluster enabled", bool(c.get("privateClusterConfig", {}).get("enablePrivateNodes")), "Enable private nodes/endpoint", "")
            add("5.6.4", f"[{n}] Master authorized networks", bool(c.get("masterAuthorizedNetworksConfig", {}).get("enabled")), "Enable master authorized networks", "")
            add("5.6.7", f"[{n}] Network policy enabled", bool(c.get("networkPolicy", {}).get("enabled")), "Enable NetworkPolicy", "")
            add("5.10.1", f"[{n}] Binary Authorization", bool(c.get("binaryAuthorization", {}).get("enabled")), "Enable Binary Authorization", "")
            add("5.5.2", f"[{n}] Shielded nodes", bool(c.get("shieldedNodes", {}).get("enabled")), "Enable shielded GKE nodes", "")
            add("5.2.1", f"[{n}] Workload Identity", bool((c.get("workloadIdentityConfig") or {}).get("workloadPool")), "Enable Workload Identity", "")
            add("5.7.1", f"[{n}] Control plane logging", c.get("loggingService", "none") not in ("none", ""), "Set loggingService to googleapis/system workloads", c.get("loggingService", ""))
            add("5.3.1", f"[{n}] Application-layer secrets encryption", bool(c.get("databaseEncryption", {}).get("keyName")), "Configure databaseEncryption with a KMS key", "")
    return out

# ---------------- mapping + report ----------------
def to_tpl(cid, desc, prov):
    s = (cid + " " + desc).lower()
    for rx, t in PROV_MAP.get(prov, []):
        if re.search(rx, s): return t
    for rx, t in MAP:
        if re.search(rx, s): return t
    return FALLBACK

def render(results, prov, outdir):
    tpl = load_tpl()
    fails = [r for r in results if r["status"] == "FAIL"]
    by, unc = {}, []
    for r in fails:
        t = r.get("template") or to_tpl(r["id"], r["desc"], prov)
        r["template"] = t
        (unc if t is None else by.setdefault(t, [])).append(r)
    bench = CISDOC.get(BENCH.get(prov, ""), "CIS Kubernetes Benchmark")
    md = [f"# CIS Kubernetes Benchmark Findings ({prov})", f"_{datetime.now(timezone.utc):%Y-%m-%d %H:%M UTC} | benchmark: {bench} | {len(results)} checks run | {len(fails)} non-compliant | {len(by)} findings_", f"_Coverage: {COVERAGE.get(prov, '')}_", "_Note: controls marked MANUAL by the benchmark require human verification and are excluded from non-compliant counts._\n", "# Template Findings\n"]
    if DENIED or PARTIAL:
        md.insert(4, f"_Access gaps: skipped entirely (no verdicts emitted): {', '.join(sorted(DENIED)) or 'none'} | reduced scope via per-namespace fallback: {', '.join(sorted(PARTIAL)) or 'none'}_")
    RANK = {"critical": 0, "high": 1, "medium": 2, "low": 3, "informational": 4}
    for t, rs in sorted(by.items(), key=lambda kv: (RANK.get(tget(tpl, kv[0]).get("risk", "medium").lower(), 2), -len(kv[1]))):
        m = tget(tpl, t)
        md.append(f"## [{m.get('risk', 'Medium').upper()}] {t}")
        md.append(f"**Risk:** {m.get('risk', 'Medium')}  |  **Category:** {m.get('cat', 'Security')}  |  **Non-compliant checks:** {len(rs)}\n")
        md.append("**Affected CIS controls:**")
        for r in rs:
            ev = r.get("evidence", "")
            parts = [p.strip() for p in ev.split(",") if p.strip()]
            evs = ev
            md.append(f"- `{r['id']}` {r['desc']}")
            if evs:
                parts2 = []
                for chunk in evs.split(","):
                    parts2.extend(p.strip() for p in chunk.split(";") if p.strip())
                for part in parts2:
                    md.append(f"  - `{part}`")
            rawc = RAWCFG.get(r["id"]) or RAWCFG.get(r["id"] + "-quota")
            if rawc:
                md.append("\n  Misconfiguration (raw):")
                md.append("  ```")
                md.append("  " + rawc.replace("\n", "\n  "))
                md.append("  ```")
        nodeset = sorted({r["node"] for r in rs if r.get("node")} | {ev.split("@", 1)[1] for r in rs for ev in re.findall(r"[\w.-]+/[\w.-]+@[\w.-]+", r.get("evidence", ""))})
        scopes = {r.get("scope", "entire cluster") for r in rs}
        if nodeset:
            md.append("\n**Affected nodes:** " + ", ".join(f"`{n}`" for n in nodeset))
        for rr in sorted({r.get("res") for r in rs if r.get("res") and RAWJSON.get(r["res"])}):
            lines, hit = raw_lines(rr, ",".join(x.get("evidence", "") for x in rs if x.get("res") == rr))
            mk = [l + "   <-- VULNERABLE" if i in hit and (i - 1) not in hit else l for i, l in enumerate(lines)]
            md.append(f"\n**Raw output (`{rr}`, vulnerable objects marked, truncated):**")
            md.append("```")
            md.append("\n".join(mk)[:2000])
            md.append("```")

        md.append("\n**Details:** " + m.get("details", "").split("[^footnote")[0][:800])
        md.append("\n**Recommendation:** " + m.get("rec", ""))
        rem = {r["remediation"] for r in rs if r.get("remediation")}
        if rem: md.append("\n**CIS remediation steps:**\n" + "\n".join(f"- {x}" for x in sorted(rem)))
        md.append("\n---\n")
    if unc:
        md.append("\n---\n")
        md.append("# Other CIS Failures (No Finding Template)")
        md.append(f"**Non-compliant checks:** {len(unc)} â€” create or map finding templates for these before reporting.\n")
        for r in unc:
            md.append(f"- `{r['id']}` {r['desc']}" + (f" â€” remediation: {r['remediation']}" if r.get("remediation") else ""))
        md.append("\n---\n")
    nsmap = {}
    for r in fails:
        for m2 in re.findall(r"([\w.-]+)/([\w.-]+)@[\w.-]+", r.get("evidence", "")):
            nsmap.setdefault(m2[0], []).append(r)
    if nsmap:
        md.append("\n---\n")
        md.append("# Per-Namespace Breakdown")
        md.append("| Namespace | Non-compliant checks | Findings |")
        md.append("|---|---|---|")
        for nsn, rrs in sorted(nsmap.items(), key=lambda kv: -len(kv[1])):
            tpls = sorted({r.get("template") or "unmapped" for r in rrs})
            md.append(f"| `{nsn}` | {len(rrs)} | {', '.join(tpls)} |")
    rep = os.path.join(outdir, "report.md")
    open(rep, "w").write("\n".join(md))
    return rep

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--provider", choices=["eks", "aks", "gke", "oke", "ack", "openshift", "vanilla"])
    ap.add_argument("--install", action="store_true")
    ap.add_argument("--skip-bench", action="store_true")
    ap.add_argument("--per-node", action="store_true", help="run kube-bench as a job on every node")
    ap.add_argument("--namespaces", nargs="+", metavar="NS", help="explicit namespace list (skips enumeration)")
    ap.add_argument("-v", "--verbose", action="store_true")
    ap.add_argument("-q", "--quiet", action="store_true")
    ap.add_argument("--show-cmds", action="store_true", help="print each command and its raw output")
    ap.add_argument("--out", default="out")
    ap.add_argument("--report")
    ap.add_argument("--templates", help="path to findings-templates.json")
    a = ap.parse_args()
    globals()["ARGS"] = a
    if a.show_cmds: globals()["SHOW_CMD"] = True
    if a.templates:
        globals()["TPL"] = a.templates
    global VERBOSE
    VERBOSE = not a.quiet
    if len(sys.argv) == 1:
        print("[*] CIS Kubernetes benchmark runner (interactive)")
        det = (detect_provider() or "vanilla").replace("-cli", "")
        if not have("kubectl") and not have("kube-bench"):
            if input("[?] no kubectl/kube-bench found, install them? [Y/n]: ").strip().lower() not in ("n", "no"):
                ensure_tools()
        a.provider = input(f"[?] provider [{det}] (eks/aks/gke/oke/ack/openshift/vanilla): ").strip().lower() or det
        a.skip_bench = input("[?] run kube-bench node/config checks? [Y/n]: ").strip().lower() in ("n", "no")
        a.per_node = input("[?] per-node mode (run kube-bench as a job on every node)? [y/N]: ").strip().lower() in ("y", "yes")
        VERBOSE = a.verbose = input("[?] verbose check-by-check output? [Y/n]: ").strip().lower() not in ("n", "no")
        globals()["SHOW_CMD"] = input("[?] show each command and its raw output? [y/N]: ").strip().lower() in ("y", "yes")
        a.out = input("[?] output directory [out]: ").strip() or "out"
    if a.install: ensure_tools()
    if a.report:
        d = json.load(open(a.report))
        RAWJSON.update(d.get("raw_outputs", {}))
        print(render(d["results"], d["provider"], os.path.dirname(a.report) or "."))
        return
    prov = (a.provider or detect_provider() or "vanilla").replace("-cli", "")
    CUR_PROV = prov
    print(f"[*] provider: {prov}")
    os.makedirs(a.out, exist_ok=True)
    results = []
    if not a.skip_bench:
        kb, err = run_bench(prov)
        if kb:
            n = 0
            for t in kb.get("Tests", []):
                for r in t.get("results", []):
                    rr = {"id": r.get("check_number", ""), "desc": r.get("check_desc", ""), "status": r.get("status", "WARN"), "remediation": r.get("remediation", ""), "evidence": (r.get("actual_value", "") or "")[:200], "src": "kube-bench"}
                    results.append(rr); show(rr)
                    n += 1
            print(f"[+] kube-bench: {n} checks")
        else:
            print(f"[-] kube-bench skipped: {err} (API and cloud checks continue)")
    if getattr(a, "per_node", False):
        pn = per_node_bench(prov); print(f"[+] per-node kube-bench: {len(pn)} results across nodes")
        results.extend(pn)
    ac = api_checks(); print(f"[+] api checks: {len(ac)}")
    cc = cli_checks(prov); print(f"[+] cli checks: {len(cc)}")
    ec = extra_checks(); print(f"[+] extra (non-CIS) checks: {len(ec)}")
    results += ac + cc + ec
    for r in results:
        r["template"] = r.get("template") or to_tpl(r["id"], r["desc"], prov)
        rc_ = RAWCFG.get(r["id"]) or RAWCFG.get(r["id"] + "-quota")
        if rc_: r["rawcfg"] = rc_
        if r.get("node"):
            r["scope"] = "node: " + r["node"]
        elif re.findall(r"[\w.-]+/[\w.-]+@[\w.-]+", r.get("evidence", "")):
            ns = sorted({m.split("@")[1] for m in re.findall(r"[\w.-]+/[\w.-]+@[\w.-]+", r["evidence"])})
            r["scope"] = ("nodes: " + ", ".join(ns)) if ns else "entire cluster"
        else:
            r["scope"] = "entire cluster"
    if VERBOSE:
        global TPLC
        if TPLC is None:
            TPLC = load_tpl()
        RANK = {"critical": 0, "high": 1, "medium": 2, "low": 3, "informational": 4}
        COL = {"HIGH": 31, "CRITICAL": 35, "MEDIUM": 33, "LOW": 36}
        mapped = sorted([r for r in results if r["status"] == "FAIL" and r["template"]],
                        key=lambda r: RANK.get(tget(TPLC, r["template"]).get("risk", "medium").lower(), 2))
        unm = [r for r in results if r["status"] == "FAIL" and not r["template"]]
        ctx = sh("kubectl config current-context")[1].strip() if have("kubectl") else ""
        cname = ctx.split("/")[-1] if ctx else prov
        print(f"\n[*] FINDINGS:\n    cluster: {cname or prov}")
        for r in mapped:
            te = tget(TPLC, r["template"])
            risk = te.get("risk", "Medium").upper()
            if not te: NORISK.add(r["template"])
            print(f"  \033[31m\u2717\033[0m {r['id']}  \033[{COL.get(risk, 37)}m[{risk}]\033[0m \033[1m{r['template']}\033[0m")
            cmd = RAWCMD.get(r.get("res") or "")
            if cmd:
                print(f"      raw output: {cmd}")
                if (r.get("res") or "") in PARTIAL:
                    print("        (cluster-scope denied for your identity; per-namespace: " + cmd.replace(" -A ", " --namespace <ns> ").replace("-A", "--namespace <ns>") + ")")
            ev = r.get("evidence", "")
            if ev:
                print("      vulnerable items:")
                parts = []
                for chunk in ev.split(","):
                    parts.extend(p.strip() for p in chunk.split(";") if p.strip())
                for part in parts:
                    print(f"        - {part}")
        print("  " + "-" * 64)
        if NORISK:
            print("[!] risk defaulted to Medium (template missing from templates file): " + ", ".join(sorted(NORISK)))
        print("[*] CIS BENCHMARK:")
        fc = [r["id"] for r in results if r["status"] == "FAIL" and r["id"] != "EXTRA"]
        fe = sum(1 for r in results if r["status"] == "FAIL" and r["id"] == "EXTRA")
        uf = ", ".join(fc) + (f", Other (x{fe})" if fe else "")
        print(f"  \033[31mFAILED ({len(fc) + fe}):\033[0m " + uf)
        pc = [r["id"] for r in results if r["status"] == "PASS" and r["id"] != "EXTRA"]
        pe = sum(1 for r in results if r["status"] == "PASS" and r["id"] == "EXTRA")
        pl = ", ".join(pc) + (f", Other (x{pe})" if pe else "")
        print(f"  \033[32mPASSED ({len(pc) + pe}):\033[0m " + pl)
    jf = os.path.join(a.out, "results.json")
    cov = {"skipped": sorted(DENIED), "reduced_scope": {r: d for r, d in sorted(PARTIAL.items())}}
    json.dump({"provider": prov, "ts": datetime.now(timezone.utc).isoformat(), "coverage": cov, "raw_outputs": RAWJSON, "results": results}, open(jf, "w"), indent=1)
    print(f"[+] {jf}")
    print(f"[+] {render(results, prov, a.out)}")
    fails = sum(1 for r in results if r["status"] == "FAIL")
    xf = sum(1 for r in results if r["status"] == "FAIL" and r.get("src") == "extra")
    RES_CHECKS = {"pods": "5.2.x pod security, 5.7.1, EXTRA pod checks",
                  "networkpolicies": "5.3.2", "resourcequotas": "5.4.x (quotas)", "limitranges": "5.4.x (limits)",
                  "serviceaccounts": "5.1.6, EKS-SA", "clusterroles": "5.1.2, 5.1.3",
                  "clusterrolebindings": "5.1.1, 5.1.x unauthenticated bindings",
                  "namespaces": "5.2.x PSS labels + every per-namespace check"}
    if DENIED:
        print("[!] checks SKIPPED entirely - no data obtainable (NOT findings, no verdicts emitted for these):")
        for r in sorted(DENIED):
            print(f"    - {r}: affects {RES_CHECKS.get(r, 'provider/other checks')}")
    if PARTIAL:
        print("[!] checks ran with REDUCED scope - cluster-wide list denied, per-namespace fallback used:")
        for r, dn in sorted(PARTIAL.items()):
            cov = (f"no access in {len(dn)}/{len(NSLIST)} namespaces: " + ", ".join(dn[:5]) + (" ..." if len(dn) > 5 else "")) if dn else f"all {len(NSLIST)} namespaces readable via fallback"
            print(f"    - {r}: {cov}")
        print("    verdicts for these cover readable namespaces only; a PASS is not cluster-wide proof")
    if MISSING_PERMS:
        print("\n[!] PERMISSIONS REQUIRED (share with the AWS / platform team):")
        for p in sorted(set(MISSING_PERMS)):
            print("    - " + p)
        print("    the current identity was denied these; grant them (read-only) and rerun")
    if not results:
        print("[!] nothing was checked - no cluster reachable and no cloud CLI available")
        print("    fastest fix: aws eks update-kubeconfig --name <cluster>  (then rerun)")
    print(f"[*] done: {len(results)} checks run: {fails - xf} CIS controls and {xf} additional checks not met")

if __name__ == "__main__":
    main()

